def _premier_rang(cond, depart=0, limite=10_000):
    """Plus petit entier n >= depart vérifiant cond(n) (recherche exhaustive)."""
    return next(i for i in range(depart, limite) if cond(i))


def _fibo(count):
    u = [1, 1]
    while len(u) < count:
        u.append(u[-1] + u[-2])
    return u


def _recurrence(u0, step, count):
    """Termes u_0 … u_{count-1} de u_{i+1} = step(u_i, i)."""
    u = [u0]
    for i in range(count - 1):
        u.append(step(u[-1], i))
    return u


